def IsClosedBelow (κ : Cardinal.{u}) (S : Set Ordinal.{u}) : Prop :=
  ∀ γ, γ < κ.ord → γ.IsLimit →
  (∀ α, α < γ → ∃ δ ∈ S, α < δ ∧ δ < γ) → γ ∈ S

theorem diagInter_isClosedBelow {κ : Cardinal.{u}} {f : Ordinal.{u} → Set Ordinal.{u}}
    (hf : ∀ β, β < κ.ord → IsClub κ (f β)) :
    IsClosedBelow κ (diagInter f)
